import time

def cronometro(func):
    def wrapper(*args, **kwargs):
        inicio = time.perf_counter()
        resultado = func(*args, **kwargs)
        fim = time.perf_counter()
        print(f"Tempo: {fim - inicio:.6f}s")
        return resultado
    return wrapper

@cronometro
def saudacao():
    return "ok"

print(saudacao())

